<?php
/** سیزده نسبت مالی: مقدار، فرمول، اقلام منبع، دورهٔ قبل، snapshot و تنظیم نگاشت. همهٔ محاسبه در RatioService است. */
namespace Agah\Erp\Http;
use Agah\Erp\Core\{Ctx,Db,Jalali,Money,Request,Settings};
use Agah\Erp\Modules\Accounting\RatioService;
if(!defined('ABSPATH'))exit;
[$from,$to]=FinanceController::dates();
$data=RatioService::compute($cid,$from,$to);$prev=RatioService::previous($cid,$from,$to);$u=Ctx::unit();
$show=function($r)use($u){if($r['value']===null)return '—';if($r['unit']==='money')return Money::fmt((int)$r['value'],$u).' '.Money::unitLabel($u);return Money::toFa(str_replace('.','٫',$r['value'])).' '.RatioService::UNITS[$r['unit']];};
$in=$data['inputs'];$m=function($v)use($u){return $v===null?'تعریف نشده':Money::fmt((int)$v,$u);};
?>
<section class="erp-card erp-print-document"><h2>نسبت‌های مالی</h2>
<form method="get" class="erp-filter erp-no-print"><input type="hidden" name="page_id" value="<?php echo (int)get_option('agah_erp_page_id'); ?>"><input type="hidden" name="c" value="<?php echo (int)$cid; ?>"><input type="hidden" name="p" value="financial_ratios"><label>از تاریخ شمسی<input name="from" value="<?php echo esc_attr(Jalali::format($from,false)); ?>" data-jalali></label><label>تا تاریخ شمسی<input name="to" value="<?php echo esc_attr(Jalali::format($to,false)); ?>" data-jalali></label><button type="submit" class="btn btn-outline">محاسبه</button></form>
<p>دوره: <?php echo esc_html(Jalali::format($from).' تا '.Jalali::format($to).'؛ '.Money::toFa($data['days']).' روز؛ واحد مبالغ: '.Money::unitLabel($u)); ?>. فقط اسناد تأییدشده و قطعی. میانگین هر قلم = (ابتدای دوره + پایان دوره) ÷ ۲.</p>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>کد</th><th>نسبت</th><th>مقدار</th><th>دورهٔ مشابه سال قبل</th><th>فرمول</th><th>توضیح</th></tr></thead><tbody>
<?php foreach($data['ratios'] as $code=>$r): ?><tr><td><?php echo esc_html($code); ?></td><td><?php echo esc_html($r['name']); ?></td><td><strong><?php echo esc_html($show($r)); ?></strong></td><td><?php echo esc_html($prev?$show($prev['ratios'][$code]):'—'); ?></td><td><?php echo esc_html($r['formula']); ?></td><td><?php echo esc_html(RatioService::DESCRIPTIONS[$code].($r['value']===null?' غیرقابل محاسبه: '.$r['reason']:'')); ?></td></tr><?php endforeach; ?>
</tbody></table></div>
<details><summary>اقلام منبع (برای تطبیق با دفاتر)</summary><div class="erp-scroll"><table class="erp-table"><thead><tr><th>قلم</th><th>ابتدای دوره</th><th>پایان دوره</th></tr></thead><tbody>
<?php foreach(['current_assets'=>'دارایی جاری','current_liabilities'=>'بدهی جاری','cash'=>'وجه نقد و معادل نقد','short_investment'=>'سرمایه‌گذاری کوتاه‌مدت','receivable'=>'دریافتنی تجاری','inventory'=>'موجودی کالا','total_assets'=>'کل دارایی‌ها','total_liabilities'=>'کل بدهی‌ها','equity'=>'حقوق صاحبان سرمایه (با سود جاری)'] as $k=>$label): ?><tr><td><?php echo esc_html($label); ?></td><td><?php echo esc_html($m($in['opening'][$k])); ?></td><td><?php echo esc_html($m($in['closing'][$k])); ?></td></tr><?php endforeach; ?>
<?php foreach(['sales'=>'فروش خالص دوره','credit_sales'=>'فروش نسیه دوره','cogs'=>'بهای تمام‌شدهٔ کالای فروش‌رفته','net_profit'=>'سود خالص دوره','interest'=>'هزینهٔ بهره','tax_expense'=>'هزینهٔ مالیات','ebit'=>'سود قبل از بهره و مالیات'] as $k=>$label): ?><tr><td><?php echo esc_html($label); ?></td><td colspan="2"><?php echo esc_html($m($in[$k])); ?></td></tr><?php endforeach; ?>
</tbody></table></div></details>
<div class="erp-no-print"><button type="button" class="btn btn-outline" data-print>چاپ / ذخیره PDF</button><?php FinanceController::exportLink($cid,'ratios'); ?>
<?php if(Ctx::can('report.export')): ?><form method="post" class="erp-inline-form"><?php self::form('module_ratio_snapshot',$cid,'financial_ratios'); ?><input type="hidden" name="from" value="<?php echo esc_attr(Jalali::format($from,false)); ?>"><input type="hidden" name="to" value="<?php echo esc_attr(Jalali::format($to,false)); ?>"><button type="submit" class="btn btn-outline">ثبت نسخهٔ ثابت این دوره</button></form><?php endif; ?></div></section>
<?php $snaps=RatioService::snapshots($cid);if($snaps): ?><section class="erp-card"><h3>نسخه‌های ثابت ثبت‌شده</h3><div class="erp-scroll"><table class="erp-table"><thead><tr><th>دوره</th><th>زمان ثبت</th><th></th></tr></thead><tbody><?php foreach($snaps as $s): ?><tr><td><?php echo esc_html(Jalali::format($s['date_from']).' تا '.Jalali::format($s['date_to'])); ?></td><td><?php echo esc_html(Jalali::format(get_date_from_gmt($s['created_at'],'Y-m-d')).' '.get_date_from_gmt($s['created_at'],'H:i')); ?></td><td><?php if(Ctx::can('report.export')): ?><form method="post" class="erp-inline-form"><?php self::form('module_ratio_snapshot_delete',$cid,'financial_ratios',$s['id']); ?><button type="submit" class="btn btn-outline btn-sm" data-confirm="نسخهٔ ثابت حذف شود؟">حذف</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if(Ctx::can('company_settings.edit')): $accounts=Db::rows('SELECT id,code,name,stmt_class,sys_key,ratio_tag FROM '.Db::t('accounts')." WHERE company_id=%d AND level=3 AND stmt_class IN ('asset_current','liability_current','finance_cost') ORDER BY code",$cid); ?>
<section class="erp-card erp-no-print"><h3>تنظیم نسبت‌ها (حسابدار)</h3><p>نگاشت پیش‌فرض از نوع حساب و کلید سیستمی است. فقط اگر حسابی باید در قلم دیگری شمرده شود برچسب بزنید.</p>
<form method="post" class="erp-form erp-ratio-config"><?php self::form('module_ratio_configure',$cid,'financial_ratios');self::select('credit_mode','روش تعیین فروش نسیه',RatioService::CREDIT_MODES,Settings::get('ratio_credit_sales',$cid)); ?>
<div class="erp-scroll"><table class="erp-table"><thead><tr><th>حساب</th><th>برچسب</th></tr></thead><tbody><?php foreach($accounts as $a): ?><tr><td><?php echo esc_html($a['code'].' — '.$a['name']); ?></td><td><select name="ratio_tag[<?php echo (int)$a['id']; ?>]"><option value="">پیش‌فرض</option><?php foreach(RatioService::TAGS as $k=>$label): ?><option value="<?php echo esc_attr($k); ?>" <?php selected((string)$a['ratio_tag'],$k); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></td></tr><?php endforeach; ?></tbody></table></div>
<button type="submit" class="btn btn-primary">ذخیرهٔ تنظیم نسبت‌ها</button></form></section><?php endif; ?>
